import { createHash } from 'node:crypto';
import { Gender } from '@/modules/registrations/domain/gender';

/**
 * `pending` waits for the organizer's decision (S3-01, spec v4 §3): a new
 * registration and a moved term start there. Only `confirmed` holds a bed and
 * creates a debt.
 */
export type ParticipationStatus =
  'pending' | 'confirmed' | 'waitlisted' | 'cancelled';

/** A submission as the API received it, already trimmed and in E.164. */
export type RegistrationInput = {
  /** Generated by the form when it is opened; the same for every retry. */
  submissionKey: string;
  firstName: string;
  lastName: string;
  /** As typed, trimmed; the identity uses `normalizeEmail` (data-model.md §3.7). */
  email: string;
  phone: string;
  termIds: string[];
  /** Voluntary (F64); left out or null is "not answered". */
  gender?: Gender | null;
  /** The own words for `other` only; left out or null is none. */
  genderOther?: string | null;
};

/** One registration per e-mail and event: trimmed and lower-cased (T1). */
export const normalizeEmail = (email: string): string =>
  email.trim().toLowerCase();

/**
 * Tells a retry of the same submission from a reused key with changed content.
 * The term order and the e-mail case do not change what is being submitted.
 * Without a gender answer the hash is the one stored before F64.
 */
export const submissionHash = (input: RegistrationInput): string =>
  createHash('sha256')
    .update(
      JSON.stringify([
        input.firstName,
        input.lastName,
        normalizeEmail(input.email),
        input.phone,
        [...input.termIds].sort(),
        ...(input.gender ? [input.gender] : []),
        ...(input.genderOther ? [input.genderOther] : []),
      ]),
    )
    .digest('hex');

const PRAGUE = 'Europe/Prague';

const pragueFormat = new Intl.DateTimeFormat('en-US', {
  timeZone: PRAGUE,
  hourCycle: 'h23',
  year: 'numeric',
  month: 'numeric',
  day: 'numeric',
  hour: 'numeric',
  minute: 'numeric',
  second: 'numeric',
});

/** Wall-clock time in Prague at `instant`, as if it were UTC. */
const pragueWallClock = (instant: number): number => {
  const part = Object.fromEntries(
    pragueFormat
      .formatToParts(new Date(instant))
      .map(({ type, value }) => [type, Number(value)]),
  );
  return Date.UTC(
    part.year,
    part.month - 1,
    part.day,
    part.hour,
    part.minute,
    part.second,
    instant % 1000,
  );
};

/**
 * The reminder date: `days` calendar days after `confirmedAt` at the same
 * Prague wall-clock time, so it holds across a DST change (S2-16). A time that
 * does not exist on the target day (the spring gap) moves to the next valid one.
 */
export const paymentReminderAt = (confirmedAt: Date, days: number): Date => {
  const instant = confirmedAt.getTime();
  const local = pragueWallClock(instant);
  const target = new Date(local);
  target.setUTCDate(target.getUTCDate() + days);
  const wanted = target.getTime();
  // The offset can change between the guesses; two rounds settle it.
  let result = wanted - (local - instant);
  for (let i = 0; i < 2; i++) {
    result = wanted - (pragueWallClock(result) - result);
  }
  return new Date(result);
};

/** Σ price of the confirmed terms in haléře; unconfirmed terms owe nothing. */
export const amountDueMinor = (
  terms: { status: ParticipationStatus; priceMinor: number }[],
): number =>
  terms
    .filter((term) => term.status === 'confirmed')
    .reduce((sum, term) => sum + term.priceMinor, 0);

/** Price of the selected terms, unconfirmed ones included; released terms are not selected. */
export const selectedPriceMinor = (
  terms: { status: ParticipationStatus; priceMinor: number }[],
): number =>
  terms
    .filter((term) => term.status !== 'cancelled')
    .reduce((sum, term) => sum + term.priceMinor, 0);

export type BankAccount = {
  prefix: string | null;
  number: string;
  bankCode: string;
};

/**
 * What the participant pays, where and when they are reminded. Stored on the
 * registration at receipt, so later event changes never touch it (S2-09).
 */
export type PaymentInstructions = {
  amountMinor: number;
  variableSymbol: string;
  account: BankAccount;
  /** Reminder, not a deadline: nothing happens to the registration when it passes. */
  reminderAt: Date;
};

/** The event a registration belongs to, as its participant sees it. */
export type EventSummary = { name: string; location: string };

export type RegistrationTermResult = {
  termId: string;
  label: string;
  startDate: string;
  endDate: string;
  priceMinor: number;
  status: ParticipationStatus;
};

/** The stored outcome of one registration, as S2-14 shows it right after submitting. */
export class RegistrationResultModel {
  constructor(
    public readonly id: string,
    public readonly receivedAt: Date,
    public readonly firstName: string,
    public readonly lastName: string,
    public readonly email: string,
    public readonly phone: string,
    /** By term start. */
    public readonly terms: RegistrationTermResult[],
    public readonly variableSymbol: string,
    public readonly account: BankAccount,
    public readonly reminderAt: Date | null,
    public readonly event: EventSummary,
    private readonly paymentToken: string,
  ) {}

  /** Token of the QR payment link (F21-1); null while nothing is owed. */
  get paymentLinkToken(): string | null {
    return this.amountDueMinor > 0 ? this.paymentToken : null;
  }

  /** Σ confirmed terms (S2-16); 0 for waitlisted-only or free terms. */
  get amountDueMinor(): number {
    return amountDueMinor(this.terms);
  }

  /** Null at zero obligation: no reminder date and no request to pay. */
  get paymentInstructions(): PaymentInstructions | null {
    if (this.amountDueMinor <= 0 || !this.reminderAt) return null;
    return {
      amountMinor: this.amountDueMinor,
      variableSymbol: this.variableSymbol,
      account: this.account,
      reminderAt: this.reminderAt,
    };
  }

  /** Price of the selected terms; not the amount due. */
  get selectedPriceMinor(): number {
    return selectedPriceMinor(this.terms);
  }
}
